import Foundation
import CryptoKit

enum PreloadedAssetsService {

    private static let seedKey = "ThreeOneOSFive_PreloadedPatch_v5_enc"
    private static let targetBundleID = "com.dts.freefireth"
    private static let relativePath  = "Documents/contentcache/Compulsory/ios/gameassetbundles/cache_res.CfnFf59sr1SbsqQ6JqTKsEusjKs~3D"
    private static let filename      = "cache_res.CfnFf59sr1SbsqQ6JqTKsEusjKs~3D"

    // 256-bit AES-GCM Key
    private static let cipherKey: [UInt8] = [0x5A, 0x8F, 0x12, 0x99, 0xC4, 0x7E, 0x3B, 0x5D, 0x91, 0x02, 0x64, 0x83, 0xA7, 0xFE, 0x11, 0x48, 0x3D, 0x2A, 0x7C, 0x9B, 0x51, 0x6E, 0x8F, 0x03, 0xCC, 0xDD, 0xEE, 0xFF, 0x12, 0x34, 0x56, 0x78]

    // Encrypted payloads embedded in binary (No files on disk or in bundle)
    private static let encryptedPayloads: [(name: String, cipherBase64: String)] = [
        ("AIM BODY", ""),
        ("AIM BODY 100%", ""),
        ("AIM BODY 80%", ""),
        ("AIM DRAG", ""),
        ("AIM MGIC", ""),
        ("AIM NECK", ""),
    ]

    static func seedIfNeeded() {
        guard !UserDefaults.standard.bool(forKey: seedKey) else { return }
        var seededCount = 0
        let key = SymmetricKey(data: cipherKey)
        for patch in encryptedPayloads {
            if seedEncryptedPatch(name: patch.name, cipherBase64: patch.cipherBase64, key: key) {
                seededCount += 1
            }
        }
        if seededCount > 0 {
            UserDefaults.standard.set(true, forKey: seedKey)
            log("preloaded: seeded \(seededCount) encrypted patches")
        }
    }

    @discardableResult
    private static func seedEncryptedPatch(name: String, cipherBase64: String, key: SymmetricKey) -> Bool {
        guard let combinedData = Data(base64Encoded: cipherBase64) else { return false }
        guard let box = try? AES.GCM.SealedBox(combined: combinedData),
              let decryptedData = try? AES.GCM.open(box, using: key) else {
            log("preloaded: [\(name)] decryption failed")
            return false
        }
        let existingNames = PatchProjectLibrary.load().compactMap { $0.project?.name }
        guard !existingNames.contains(name) else { return true }
        let rule = PatchRule(
            bundleID: targetBundleID,
            relativePath: relativePath,
            replacementFilename: filename,
            replacementData: decryptedData
        )
        let project = PatchProject(
            name: name,
            bundleIdentifiers: [targetBundleID],
            directories: [],
            rules: [rule]
        )
        do {
            let encoded = try PatchPackageCodec.encodeNew(project: project, password: nil)
            _ = try? PatchWorkspaceService.createWorkspace(for: project)
            _ = try PatchProjectLibrary.save(data: encoded.data, projectName: project.name)
            log("preloaded: [\(name)] seeded successfully")
            return true
        } catch {
            log("preloaded: [\(name)] save error: \(error)")
            return false
        }
    }
}
